CREATE DATABASE SCOPED CREDENTIAL mikecredential
WITH
    IDENTITY = 'Managed Identity';



   CREATE EXTERNAL DATA SOURCE raw_ext_source
WITH
(
    TYPE = HADOOP,
    LOCATION = 'abfss://raw@azureadlsgen2storage.dfs.core.windows.net',
    CREDENTIAL = mikecredential
);


CREATE EXTERNAL FILE FORMAT raw_parquet_format
WITH
(
    FORMAT_TYPE = PARQUET
);
